#include "bc2_sign.h"
#include <openssl/ec.h>
#include <openssl/ecdsa.h>
#include <openssl/obj_mac.h>
#include <string.h>
static EC_KEY* key_priv(const uint8_t k[32]){EC_KEY*e=EC_KEY_new_by_curve_name(NID_secp256k1);BIGNUM*b=BN_bin2bn(k,32,NULL);const EC_GROUP*g=e?EC_KEY_get0_group(e):NULL;EC_POINT*q=g?EC_POINT_new(g):NULL;if(!e||!b||!q||EC_KEY_set_private_key(e,b)!=1||EC_POINT_mul(g,q,b,NULL,NULL,NULL)!=1||EC_KEY_set_public_key(e,q)!=1){EC_KEY_free(e);e=NULL;}EC_POINT_free(q);BN_clear_free(b);return e;}
bool bc2_ecdsa_sign_der(const uint8_t k[32],const uint8_t h[32],uint8_t*out,size_t cap,size_t*n){if(!k||!h||!out||!n)return false;*n=0;EC_KEY*e=key_priv(k);if(!e)return false;ECDSA_SIG*s=ECDSA_do_sign(h,32,e);if(!s){EC_KEY_free(e);return false;}const BIGNUM*r,*ss;ECDSA_SIG_get0(s,&r,&ss);const EC_GROUP*g=EC_KEY_get0_group(e);BIGNUM*ord=BN_new(),*half=BN_new(),*low=BN_dup(ss);BN_CTX*c=BN_CTX_new();bool ok=ord&&half&&low&&c&&EC_GROUP_get_order(g,ord,c)==1&&BN_rshift1(half,ord)==1;if(ok&&BN_cmp(low,half)>0)ok=BN_sub(low,ord,low)==1;if(ok){BIGNUM*rr=BN_dup(r);ECDSA_SIG*canon=ECDSA_SIG_new();ok=rr&&canon&&ECDSA_SIG_set0(canon,rr,low)==1;low=NULL;if(ok){int len=i2d_ECDSA_SIG(canon,NULL);if(len>0&&(size_t)len<=cap){unsigned char*p=out;ok=i2d_ECDSA_SIG(canon,&p)==len;*n=ok?(size_t)len:0U;}else ok=false;}ECDSA_SIG_free(canon);}BN_free(low);BN_free(ord);BN_free(half);BN_CTX_free(c);ECDSA_SIG_free(s);EC_KEY_free(e);return ok;}
bool bc2_ecdsa_verify_der(const uint8_t pub[33],const uint8_t h[32],const uint8_t*sig,size_t n){if(!pub||!h||!sig)return false;EC_KEY*e=EC_KEY_new_by_curve_name(NID_secp256k1);const EC_GROUP*g=e?EC_KEY_get0_group(e):NULL;EC_POINT*q=g?EC_POINT_new(g):NULL;bool ok=e&&q&&EC_POINT_oct2point(g,q,pub,33,NULL)==1&&EC_KEY_set_public_key(e,q)==1&&n<=2147483647U&&ECDSA_verify(0,h,32,sig,(int)n,e)==1;EC_POINT_free(q);EC_KEY_free(e);return ok;}
